package jsonparser

import (
	"bytes"
	"errors"
	"fmt"
	d "runtime/debug"
	"strconv"
)

// Find position of next character which is not ' ', ',', '}' or ']'
func nextValue(data []byte) (offset int) {
	for true {
		if len(data) == offset {
			return -1
		}

		if data[offset] != ' ' && data[offset] != '\n' && data[offset] != ',' {
			return
		}

		offset++
	}

	return -1
}

// Tries to find the end of string
// Support if string contains escaped quote symbols.
func stringEnd(data []byte) int {
	i := 0

	for len(data) > i {
		if data[i] != '"' {
			i++
			continue
		}

		// If it just escaped \", continue
		if i >= 1 && data[i-1] == '\\' {
			i++
			continue
		} else {
			return i + 1
		}
	}

	return -1
}

// Find end of the data structure, array or object.
// For array openSym and closeSym will be '[' and ']', for object '{' and '}'
// Know about nested structures
func trailingBracket(data []byte, openSym byte, closeSym byte) int {
	level := 0
	i := 0
	ln := len(data)

	for true {
		if i >= ln {
			return -1
		}

		c := data[i]

		// If inside string, skip it
		if c == '"' {
			//sFrom := i
			i++

			se := stringEnd(data[i:])
			if se == -1 {
				return -1
			}
			i += se - 1
		}

		if c == openSym {
			level++
		} else if c == closeSym {
			level--
		}

		i++

		if level == 0 {
			break
		}
	}

	return i
}

func searchKeys(data []byte, keys ...string) int {
	keyLevel := 0
	level := 0
	i := 0
	ln := len(data)
	lk := len(keys)

	for true {
		if i >= ln {
			return -1
		}

		// If inside string, skip it
		if data[i] == '"' {
			i++

			se := stringEnd(data[i:])
			if se == -1 {
				return -1
			}

			if ln > i+se &&
				data[i+se] == ':' && // if string is a Key, and key level match
				keyLevel == level-1 && // If key nesting level match current object nested level

				// Checks to speedup key comparsion
				len(keys[level-1]) == se-1 && // if it have same length
				data[i] == keys[level-1][0] { // If first character same
				if bytes.Equal([]byte(keys[level-1]), data[i:i+se-1]) {
					keyLevel++
					// If we found all keys in path
					if keyLevel == lk {
						return i + se + 1
					}
				}
			}

			i += se - 1
		} else if data[i] == '{' {
			level++
		} else if data[i] == '}' {
			level--
		} else if data[i] == '[' {
			// Do not search for keys inside arrays
			aOff := trailingBracket(data[i:], '[', ']')
			i += aOff
		}

		i++
	}

	return -1
}

